    pub fn option_persistent_id<T: Into<Box<str>>>(mut self, val: T) -> Self {
        self.option_persistent_ids = self
            .option_persistent_ids
            .into_vec()
            .into_iter()
            .chain(Some(val.into()))
            .collect();
        self
    }
